<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ArrowLeft, ArrowRight, Check, CircleCheck, Copy, CreditCard, FileText, LoaderCircle, RefreshCw } from 'lucide-vue-next';
import PageHeading from '../components/PageHeading.vue';
import CryptoOrderPayment from '../components/CryptoOrderPayment.vue';
import { type CryptoOptions, supportsPaymentPurpose } from '../lib/cryptoPayments';
import { usePaymentModule } from '../lib/paymentModule';
const {enabled:moduleEnabled,error:moduleError,loaded:moduleLoaded,refresh:refreshModule}=usePaymentModule();
import { usePanelContext } from '../composables/panelContext';
import { useCommerce, money, stamp, stateText, paymentStateText, canResumePayment, paymentCheckoutURL, preparePaymentWindow, type PaymentAttempt, type PaymentCheckout, type Order, type PaymentMethod, type Wallet } from '../lib/commerce';
import { mergeHistory } from '../components/member/flow';
import { bytes } from '../lib/format';
import { isCancelled } from '../lib/api';
import { serialPoll } from '../lib/requests';
import { t } from '../i18n';
import '../commerce.css';
import '../styles/member-ui.css';
const route=useRoute(),router=useRouter(),{owner,state,refresh}=usePanelContext();
const {api,read,run,busy,error,notice}=useCommerce();
const items=ref<Order[]>([]),methods=ref<PaymentMethod[]>([]),wallet=ref<Wallet|null>(null),attempts=ref<PaymentAttempt[]>([]),all=ref(false),refundID=ref(''),password=ref('');
const loading=ref(true),loadingMore=ref(false),hasMore=ref(false),filter=ref('all'),acting=ref(''),checkoutID=ref(String(route.query.checkout||'')),payment=ref('balance'),paymentURL=ref('');
const checkoutOrder=ref<Order|null>(null),checkoutLoading=ref(!!checkoutID.value),checkoutError=ref('');
const refundForm=ref<HTMLFormElement|null>(null),checkoutPanel=ref<HTMLElement|null>(null);
const refundOrder=computed(()=>items.value.find(order=>order.id===refundID.value)||(checkoutOrder.value?.id===refundID.value?checkoutOrder.value:null));
const filters=[{id:'all',label:'全部订单'},{id:'pending',label:'待处理'},{id:'completed',label:'已完成'},{id:'refund',label:'退款'}];
const visible=computed(()=>items.value.filter(o=>filter.value==='all'||(filter.value==='pending'?['pending','provisioning'].includes(o.state):filter.value==='refund'?['refund_requested','refunding','refund_pending','refunded'].includes(o.state):o.state==='completed')));
const checkout=computed(()=>checkoutOrder.value?.id===checkoutID.value?checkoutOrder.value:null);
const insufficient=computed(()=>!!checkout.value&&!!wallet.value&&BigInt(wallet.value.available)<BigInt(checkout.value.offer.price));
const ownCheckout=computed(()=>checkout.value?.user_id===state.value?.me.id);
const checkoutAttempt=computed(()=>attempts.value.find(p=>p.id===checkout.value?.payment_attempt_id));
const awaitingActivation=computed(()=>!!checkoutAttempt.value&&['paid','completed'].includes(checkoutAttempt.value.state));
const pendingCount=computed(()=>items.value.filter(o=>['pending','provisioning'].includes(o.state)).length);
let sequence=0,checkoutSequence=0,scope=0,expandedHistory=false,disposed=false;
async function loadCheckout(){
  const id=checkoutID.value,current=++checkoutSequence,context=scope;checkoutError.value='';if(!id){checkoutLoading.value=false;return}checkoutLoading.value=true;
  const query=new URLSearchParams({id});if(owner.value){const user=String(route.query.user_id||'');if(user)query.set('user_id',user);else query.set('all','1')}
  try{const result=await api<{items:Order[]}>('/orders?'+query);if(disposed||current!==checkoutSequence||context!==scope||id!==checkoutID.value)return;const value=result.items.find(order=>order.id===id);const activated=value?.state==='completed'&&checkoutOrder.value?.id===id&&checkoutOrder.value.state!=='completed';checkoutOrder.value=value||null;if(!value)checkoutError.value=t('未找到此订单，或你无权查看。请核对订单号后重试。');if(activated)void refresh().catch(()=>{});}
  catch(reason){if(!disposed&&current===checkoutSequence&&!isCancelled(reason))checkoutError.value=reason instanceof Error?t(reason.message):t('请求失败')}
  finally{if(current===checkoutSequence)checkoutLoading.value=false}
}
async function load(manual=false){
  const current=++sequence,context=scope;if(manual){loading.value=true;error.value=''}
  try {const v=await read<{items:Order[]}>('/orders'+(all.value?'?all=1':''));if(v&&current===sequence&&context===scope&&!disposed){const activated=v.items.some(o=>o.state==='completed'&&items.value.some(old=>old.id===o.id&&old.state!=='completed'));items.value=mergeHistory(items.value,v.items);if(!expandedHistory)hasMore.value=v.items.length>=50;if(activated)void refresh().catch(()=>{});}if(current===sequence&&context===scope&&checkoutID.value&&!disposed)await Promise.all([loadCheckout(),loadAttempts()]);}
  finally{if(current===sequence)loading.value=false}
}
async function refreshCheckout(){await Promise.all([load(true),loadPaymentOptions(),refreshModule()])}
async function loadAttempts(){const value=await read<{items:PaymentAttempt[]}>('/payments');if(value&&!disposed){attempts.value=value.items;const current=checkoutAttempt.value;if(current&&(!canResumePayment(current)||!current.checkout_url))paymentURL.value=''}}
async function loadPaymentOptions(){const [m,w,c]=await Promise.all([read<{items:PaymentMethod[]}>('/payment-methods'),read<Wallet>('/wallet'),read<CryptoOptions>('/crypto/options'),loadAttempts()]);if(disposed)return;if(m)methods.value=m.items.filter(item=>item.enabled&&item.checkout&&!item.archived&&supportsPaymentPurpose(item,'order'));if(c?.enabled&&!methods.value.some(m=>m.id==='crypto'))methods.value.push({id:'crypto',code:'evm_crypto',name:t('加密货币'),enabled:true,version:1,checkout:true,purposes:['order']});if(w)wallet.value=w;selectPayment();}
function selectPayment(){const order=checkout.value;payment.value=order?.payment_attempt_id?order.payment_provider_id||'':'balance';}
async function more(){const context=scope,last=items.value.at(-1);if(!last||loadingMore.value)return;loadingMore.value=true;try{const v=await read<{items:Order[]}>('/orders?before='+encodeURIComponent(last.id)+(all.value?'&all=1':''));if(v&&context===scope&&!disposed){items.value=mergeHistory(items.value,v.items);hasMore.value=v.items.length>=50;expandedHistory=true}}finally{loadingMore.value=false}}
function acceptOrder(value:Order){sequence++;checkoutSequence++;checkoutLoading.value=false;if(items.value.some(order=>order.id===value.id))items.value=mergeHistory(items.value,[value]);if(checkoutID.value===value.id)checkoutOrder.value=value;if(value.state==='completed')void refresh().catch(()=>{});}
async function action(order:Order,kind:string){
  if(busy.value)return;acting.value=order.id;
  try{const value=await run<Order>('/orders/action',{id:order.id,action:kind,...(kind==='refund'?{password:password.value}:{})});if(kind==='refund')password.value='';if(value){acceptOrder(value);refundID.value='';notice.value=kind==='request_refund'?t('退款申请已提交，等待管理员审核。'):t('订单状态已更新');await load();const latest=await read<Wallet>('/wallet');if(latest)wallet.value=latest;}}
  finally{acting.value=''}
}
async function pay(order:Order){
  if(busy.value||!moduleEnabled.value)return;
  const existing=attempts.value.find(p=>p.id===order.payment_attempt_id);
  if(existing&&['paid','completed','refund_required','refund_pending','refunded','expired','cancelled'].includes(existing.state)){notice.value=paymentStateText(existing.state);await load(true);return}
  const method=order.payment_attempt_id?order.payment_provider_id:payment.value==='balance'?'':payment.value;
  if(!method){error.value=t('当前没有可用的在线支付方式');return}if(method==='crypto')return;
  const popup=preparePaymentWindow();acting.value=order.id;paymentURL.value='';
  try{
    const value=existing&&canResumePayment(existing)&&existing.checkout_url?{attempt:existing,checkout_url:existing.checkout_url}:await run<PaymentCheckout>('/orders/pay',{order_id:order.id,payment_method:method});
    if(!value){popup.close();return}
    attempts.value=mergeHistory(attempts.value,[value.attempt]);
    if(canResumePayment(value.attempt)&&value.checkout_url){paymentURL.value=paymentCheckoutURL(value.checkout_url);popup.open(paymentURL.value);notice.value=t('请完成支付，套餐开通结果将自动更新。')}
    else{popup.close();notice.value=paymentStateText(value.attempt.state)}
    await load();
  }catch(reason){popup.close();error.value=reason instanceof Error?t(reason.message):t('请求失败')}
  finally{acting.value=''}
}
async function confirmPayment(){const order=checkout.value;if(!order||order.state!=='pending'||!ownCheckout.value||!moduleEnabled.value)return;if(payment.value==='balance'&&!order.payment_attempt_id)await action(order,'confirm');else await pay(order);}
async function reviewRefund(order:Order){if(busy.value)return;refundID.value=order.id;password.value='';await nextTick();refundForm.value?.scrollIntoView({block:'center',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});refundForm.value?.querySelector('input')?.focus({preventScroll:true})}
async function showCheckout(order:Order){checkoutID.value=order.id;checkoutOrder.value=order;paymentURL.value='';error.value='';notice.value='';await router.replace({query:{...route.query,checkout:order.id,...(owner.value?{user_id:order.user_id}:{})}});await loadPaymentOptions();await nextTick();checkoutPanel.value?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});checkoutPanel.value?.focus({preventScroll:true});}
async function closeCheckout(){checkoutID.value='';checkoutOrder.value=null;checkoutSequence++;checkoutLoading.value=false;checkoutError.value='';refundID.value='';password.value='';paymentURL.value='';const query={...route.query};delete query.checkout;delete query.user_id;await router.replace({query});}
async function copy(id:string){try{await navigator.clipboard.writeText(id);notice.value=t('单号已复制')}catch{error.value=t('复制失败，请手动选择单号')}}
watch([()=>route.query.checkout,()=>route.query.user_id],([value])=>{checkoutID.value=String(value||'');if(checkoutOrder.value?.id!==checkoutID.value)checkoutOrder.value=null;void loadCheckout()});
watch(()=>checkout.value?.id,()=>{paymentURL.value='';selectPayment()});
watch(()=>checkout.value?.payment_attempt_id,()=>{if(checkout.value?.payment_attempt_id)selectPayment()});
watch(all,()=>{scope++;sequence++;items.value=[];hasMore.value=false;expandedHistory=false;refundID.value='';password.value='';void closeCheckout();void load(true)});
const poll=serialPoll(async()=>{if(!document.hidden&&!busy.value&&!loading.value&&!loadingMore.value&&(items.value.some(o=>['pending','provisioning','refund_requested','refunding','refund_pending'].includes(o.state))||!!checkout.value&&['pending','provisioning','refund_requested','refunding','refund_pending'].includes(checkout.value.state)))await load()},()=>10000);
onMounted(async()=>{await Promise.all([load(),loadPaymentOptions()]);if(!disposed)poll.start()});
onUnmounted(()=>{disposed=true;scope++;sequence++;checkoutSequence++;password.value='';poll.stop()});
</script>
<template>
  <section class="commerce-page member-page orders-page" :aria-busy="loading">
    <PageHeading :title="checkoutID?t('确认订单'):owner?t('订单管理'):t('我的订单')" :description="checkout?t('核对套餐和金额，确认后再完成付款。'):t('开通进度、付款与售后，都在这里。')" eyebrow="ORDERS"><template #actions><button v-if="checkoutID" :disabled="busy" @click="closeCheckout"><ArrowLeft :size="16"/>{{t('返回订单列表')}}</button><RouterLink v-else class="member-link" to="/shop">{{owner?t('套餐上架'):t('选择套餐')}}<ArrowRight :size="16"/></RouterLink></template></PageHeading>
    <p v-if="error" class="error member-feedback" role="alert">{{error}}<button :disabled="loading||busy" @click="refreshCheckout">{{t('重试')}}</button></p><p v-if="notice" class="member-feedback" role="status"><CircleCheck :size="17"/>{{notice}}</p><p v-if="checkoutError&&checkout" class="error member-feedback" role="alert">{{checkoutError}}<button :disabled="checkoutLoading||busy" @click="loadCheckout">{{t('重试')}}</button></p>
    <p v-if="moduleError" class="error member-feedback" role="alert">{{moduleError}}<button @click="refreshModule">{{t('重试')}}</button></p><p v-else-if="moduleLoaded&&!moduleEnabled" class="member-hint" role="status">{{t('本站暂未开放新付款，历史订单和已到账款项仍会继续核对。')}}</p>
    <template v-if="checkout">
      <ol class="checkout-steps" :aria-label="t('开通步骤')"><li class="done"><Check :size="16"/><span>{{t('选择套餐')}}</span></li><li :class="{done:['provisioning','completed','refund_requested','refunding','refund_pending','refunded'].includes(checkout.state),active:checkout.state==='pending'}"><span class="step-number">2</span><span>{{t('确认与支付')}}</span></li><li :class="{done:checkout.state==='completed',active:checkout.state==='provisioning'}"><span class="step-number">3</span><span>{{t('开始使用')}}</span></li></ol>
      <div ref="checkoutPanel" class="checkout-layout" :class="{'crypto-order-layout':payment==='crypto'}" tabindex="-1"><article class="member-panel checkout-summary"><div class="member-panel-title"><div><span class="member-label">{{checkout.action==='renew'?t('套餐续费'):t('套餐开通')}}</span><h2>{{checkout.offer.plan.name}}</h2></div><span :class="['member-status',checkout.state]">{{stateText(checkout.state)}}</span></div><p v-if="checkout.offer.plan.description" class="member-copy">{{checkout.offer.plan.description}}</p><dl class="member-facts"><div><dt>{{t('有效期')}}</dt><dd>{{checkout.offer.plan.valid_days?checkout.offer.plan.valid_days+' '+t('天'):t('永久有效')}}</dd></div><div><dt>{{t('周期额度')}}</dt><dd>{{checkout.offer.plan.quota?bytes(checkout.offer.plan.quota):t('不限')}}</dd></div><div><dt>{{t('配额周期')}}</dt><dd>{{checkout.offer.plan.cycle==='30d'?t('每 30 天'):checkout.offer.plan.cycle==='month'?t('每自然月'):t('不自动重置')}}</dd></div><div><dt>{{t('创建时间')}}</dt><dd>{{stamp(checkout.created)}}</dd></div></dl><div class="checkout-total"><span>{{t('订单金额')}}</span><strong>{{money(checkout.offer.price)}}</strong></div><p v-if="checkout.action==='renew'" class="member-hint">{{t('续费只延长有效期，不清空当前周期用量。')}}</p><details class="member-disclosure"><summary>{{t('订单详情')}}</summary><p class="commerce-id">{{checkout.id}}</p><button @click="copy(checkout.id)"><Copy :size="15"/>{{t('复制单号')}}</button><p class="member-label">{{t('套餐版本')}} · v{{checkout.offer.plan.version}}</p><p v-if="owner" class="member-label">{{t('用户')}} #{{checkout.user_id}}</p></details></article>
      <article class="member-panel checkout-payment">
        <template v-if="checkout.state==='pending'&&ownCheckout&&moduleEnabled"><h2>{{t('确认与支付')}}</h2><p class="member-label">{{t('订单有效至')}} {{stamp(checkout.expires)}}</p><fieldset v-if="!checkout.payment_attempt_id" class="payment-options" :disabled="busy"><legend>{{t('选择支付方式')}}</legend><label :class="{selected:payment==='balance'}"><input v-model="payment" type="radio" value="balance"/><span><strong>{{checkout.offer.price==='0'?t('免费开通'):t('使用余额')}}</strong><small>{{t('可用余额')}} {{wallet?money(wallet.available):'—'}}</small></span></label><label v-for="method in checkout.offer.price==='0'?[]:methods" :key="method.id" :class="{selected:payment===method.id}"><input v-model="payment" type="radio" :value="method.id"/><span><strong>{{method.name}}</strong><small>{{method.id==='crypto'?t('链上付款，确认后自动开通'):t('在线支付')}}</small></span></label></fieldset><template v-else-if="payment!=='crypto'"><p class="member-hint"><CreditCard :size="18"/>{{checkoutAttempt?paymentStateText(checkoutAttempt.state):t('在线支付已创建，请完成支付。')}}</p><p class="member-label">{{methods.find(method=>method.id===checkout?.payment_provider_id)?.name||t('订单创建时选择的支付方式')}}</p><p v-if="awaitingActivation" class="payment-note">{{t('付款已由平台确认，正在开通套餐，请勿重复支付。')}}</p></template><div v-if="payment==='balance'&&insufficient&&!checkout.payment_attempt_id" class="member-hint"><p>{{t('当前余额不足，请充值后返回此订单继续。')}}<RouterLink class="member-link" :to="{path:'/wallet',query:{return_order:checkout.id}}">{{t('前往充值')}}<ArrowRight :size="15"/></RouterLink></p></div><template v-if="payment!=='crypto'"><button class="primary checkout-confirm" :disabled="busy||(payment==='balance'&&insufficient&&!checkout.payment_attempt_id)||(!payment&&!!checkout.payment_attempt_id)" @click="confirmPayment"><LoaderCircle v-if="busy" :size="17" class="spin"/><template v-if="busy">{{t('处理中…')}}</template><template v-else>{{awaitingActivation?t('查询开通结果'):checkout.payment_attempt_id?t('继续在线支付'):payment==='balance'?(checkout.offer.price==='0'?t('确认免费开通'):t('确认使用余额')):t('确认并前往支付')}}</template></button><a v-if="paymentURL" class="member-link" :href="paymentURL" target="_blank" rel="noopener noreferrer">{{t('打开支付页面')}}<ArrowRight :size="16"/></a><p class="payment-note">{{checkout.offer.price==='0'?t('此订单免费，确认后开始开通，无需扣款。'):payment==='balance'?t('确认后冻结对应余额，开通成功后扣减。'):t('支付结果将自动更新，完成后即可开始连接。')}}</p></template><button v-if="payment!=='crypto'" :disabled="busy" @click="action(checkout,'cancel')">{{t('取消订单')}}</button></template>
        <template v-else-if="checkout.state==='provisioning'"><div class="checkout-result"><LoaderCircle :size="32" class="spin"/><h2>{{t('正在为你开通')}}</h2><p>{{t('订单正在处理，完成后这里会自动更新。')}}</p></div><button :disabled="busy" @click="action(checkout,'cancel')">{{t('取消订单')}}</button></template>
        <template v-else-if="checkout.state==='completed'"><div class="checkout-result"><CircleCheck :size="38"/><h2>{{t('套餐已生效')}}</h2><p>{{t('现在可以选择客户端，导入订阅开始连接。')}}</p></div><RouterLink class="member-button primary" to="/subscription?connect=1">{{t('开始连接')}}<ArrowRight :size="17"/></RouterLink><button v-if="!owner&&ownCheckout" :disabled="busy" @click="action(checkout,'request_refund')">{{t('申请退款')}}</button><button v-if="owner" @click="reviewRefund(checkout)">{{t('审核整单退款')}}</button></template>
        <template v-else><div class="checkout-result"><FileText :size="32"/><h2>{{stateText(checkout.state)}}</h2><p v-if="checkout.state==='refund_requested'">{{owner?t('用户已提交退款申请，请审核。'):t('退款申请已提交，等待管理员审核。')}}</p><p v-if="checkout.message">{{t(checkout.message)}}</p></div><button v-if="owner&&!ownCheckout&&checkout.state==='pending'" :disabled="busy" @click="action(checkout,'cancel')">{{t('取消订单')}}</button><button v-if="owner&&checkout.state==='refund_requested'" @click="reviewRefund(checkout)">{{t('审核退款申请')}}</button><RouterLink v-if="['failed','cancelled','expired'].includes(checkout.state)" class="member-link" to="/shop">{{t('重新选择套餐')}}<ArrowRight :size="16"/></RouterLink></template>
        <CryptoOrderPayment v-if="(ownCheckout||owner)&&payment==='crypto'" :key="checkout.id" :order="checkout" :read-only="!ownCheckout||!moduleEnabled" @updated="load()"/><button v-if="ownCheckout&&checkout.state==='pending'&&(payment==='crypto'||!moduleEnabled)" :disabled="busy" @click="action(checkout,'cancel')">{{t('取消订单')}}</button><p v-if="checkout.message&&!['failed','cancelled','expired'].includes(checkout.state)" class="member-label">{{t(checkout.message)}}</p><button v-if="payment!=='crypto'" :disabled="loading||busy" @click="refreshCheckout"><RefreshCw :size="16" :class="{spin:loading}"/>{{t('刷新状态')}}</button><RouterLink class="member-link" :to="{path:'/tickets',query:{order:checkout.id}}">{{t('需要帮助')}}<ArrowRight :size="15"/></RouterLink>
      </article></div>
    </template>
    <div v-else-if="checkoutID" class="member-empty" :role="checkoutLoading?'status':'alert'"><template v-if="checkoutLoading"><LoaderCircle :size="25" class="spin"/><p>{{t('正在读取订单…')}}</p></template><template v-else><FileText :size="30"/><h2>{{t('订单暂不可用')}}</h2><p>{{checkoutError}}</p><p class="commerce-id">{{checkoutID}}</p><button :disabled="busy" @click="loadCheckout">{{t('重试')}}</button></template></div>
    <template v-else>
      <div class="member-toolbar"><div class="member-tabs" role="group" :aria-label="t('订单状态')"><button v-for="f in filters" :key="f.id" :aria-pressed="filter===f.id" @click="filter=f.id">{{t(f.label)}}<span v-if="f.id==='pending'&&pendingCount" class="tab-count">{{pendingCount}}</span></button></div><div class="member-actions"><label v-if="owner" class="inline-check"><input v-model="all" :disabled="busy" type="checkbox"/>{{t('查看全部成员订单')}}</label><button :disabled="loading||busy" @click="refreshCheckout"><RefreshCw :size="16" :class="{spin:loading}"/>{{t('刷新')}}</button></div></div>
      <div v-if="loading&&!items.length" class="member-empty" role="status"><LoaderCircle :size="24" class="spin"/><p>{{t('正在加载记录…')}}</p></div><div v-else-if="!visible.length&&!error" class="member-empty"><FileText :size="30"/><h2>{{items.length?t('当前筛选下暂无订单'):t('暂无订单')}}</h2><p>{{t('购买套餐后，可在这里完成付款并查看开通结果。')}}</p><button v-if="filter!=='all'" @click="filter='all'">{{t('全部订单')}}</button><RouterLink v-else class="member-link" to="/shop">{{owner?t('套餐上架'):t('选择套餐')}}<ArrowRight :size="16"/></RouterLink></div>
