      <div v-if="hasMore" class="order-pagination"><p class="member-label">{{t('筛选仅作用于已加载订单，可继续加载更多。')}}</p><button :disabled="loadingMore||loading" @click="more"><LoaderCircle v-if="loadingMore" :size="16" class="spin"/>{{loadingMore?t('加载中…'):t('加载更多')}}</button></div>
    </template>
    <form v-if="refundID&&owner" ref="refundForm" class="member-panel refund-form" @submit.prevent="refundOrder&&action(refundOrder,'refund')"><h2>{{t('审核整单退款')}}</h2><p class="commerce-id">{{refundID}}</p><p class="member-label">{{refundOrder?.payment_attempt_id?t('通过审核后先撤回权益，再到在线支付设置中处理原路退款；此处不会退入用户余额。'):t('系统先撤回对应权益，再将订单金额退回用户余额。后续权益有变化时不能自动退款。')}}</p><label>{{t('管理员当前密码')}}<input v-model="password" type="password" autocomplete="current-password" required/></label><div class="member-actions"><button class="danger-button" :disabled="busy">{{t('确认退款')}}</button><button type="button" :disabled="busy" @click="refundID='';password=''">{{t('取消')}}</button></div></form>
  </section>
</template>
